def solve():
    import sys
    import bisect

    def check(marks):
        total_sum = sum(marks)
        if total_sum > x:
            return False

        combined_marks = sorted(a + marks)
        median = combined_marks[n // 2]
        if median < y:
            return False

        return True

    n, k, p, x, y = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))

    remaining_tests = n - k
    if remaining_tests == 0:
        if sum(a) <= x and a[n // 2] >= y:
            print(" ".join(map(str, a)))
        else:
            print("-1")
        return

    # Try to find a valid set of marks for the remaining tests
    for i in range(1, p + 1):
        marks = [i] * remaining_tests
        if check(marks):
            print(" ".join(map(str, marks)))
            return

    print("-1")

if __name__ == "__main__":
    solve()
